@cute.kernel
def hybrid_kernel(data: cute.Tensor, tile_m: cutlass.Constexpr, tile_n: cutlass.Constexpr, num_tiles: cutlass.Int32):
    for tile_idx in range(num_tiles):
        for i in cutlass.range_constexpr(tile_m):
            for j in cutlass.range_constexpr(tile_n):
                idx = tile_idx * tile_m * tile_n + i * tile_n + j
                process(data[idx])
